cmd:
cd /app && mkdir -p /tmp/ref && for f in test/*.scm; do
  base=$(basename "$f")
  case "$base" in
    calculator.scm) printf '(+ 7 8)\n' > /tmp/in.txt ;;
    06-interactive-io.scm) printf '3\n4\n+\n' > /tmp/in.txt ;;
    test_read.scm) printf 'hello\n' > /tmp/in.txt ;;
    *) : > /tmp/in.txt ;;
  esac
  python3 interp.py "$f" < /tmp/in.txt > "/tmp/ref/$base.out" 2>&1
  echo "=== $base (exit $?) ==="
done
echo "ALL DONE"

cd /app && mkdir -p _ref && for f in test/*.scm; do
  base=$(basename "$f")
  case "$base" in
    calculator.scm) printf '(+ 7 8)\n' > _ref/in.txt ;;
    06-interactive-io.scm) printf '3\n4\n+\n' > _ref/in.txt ;;
    test_read.scm) printf 'hello\n' > _ref/in.txt ;;
    *) : > _ref/in.txt ;;
  esac
  python3 interp.py "$f" < _ref/in.txt > "_ref/$base.out" 2>&1
  echo "=== $base (exit $?) ==="
done
echo "ALL DONE"

cd /app && for f in test/*.scm; do
  base=$(basename "$f")
  case "$base" in
    calculator.scm) printf 'test/%s\n(+ 7 8)\n' "$base" > _ref/in2.txt ;;
    06-interactive-io.scm) printf 'test/%s\n3\n4\n+\n' "$base" > _ref/in2.txt ;;
    test_read.scm) printf 'test/%s\nhello\n' "$base" > _ref/in2.txt ;;
    *) printf 'test/%s\n' "$base" > _ref/in2.txt ;;
  esac
  depth=$(timeout 60 python3 interp.py eval.scm < _ref/in2.txt 2>&1 | grep "MAXDEPTH" | awk '{print $2}')
  echo "$depth  $base"
done | sort -rn
